## Own acquisition, replacement and release

A resource owner has one lifecycle from acquisition to release. Establish:

- who acquires, publishes and disposes it;
- what happens if acquisition fails partway through;
- how replacement invalidates the previous instance and pending callbacks;
- which cleanup operations are safe to repeat;
- whether a consumer is borrowing a shared resource or owns it exclusively.

A disposer returned by a subscription should remove that registration only.
Cleanup from an old component must not destroy a replacement owned by another
mount. Do not close a shared connection whenever one subscriber disappears.
Use framework cleanup where possible; choose a class/closure only if it makes
resource identity and lifecycle clearer than the existing owner.

'use client'

import {
  createContext,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  type Ref,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'

import {
  focusElement,
  getFocusableElements,
  isTopDialog,
  registerDialogLayer,
} from './dialog-layer'

export type DialogOpenChangeReason = 'close' | 'escape' | 'outside-pointer' | 'trigger'

export type DialogOpenChangeDetails = {
  reason: DialogOpenChangeReason
}

export type DialogRootProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void
  open?: boolean
}

type DialogContextValue = {
  contentRef: RefObject<HTMLDivElement | null>
  contentId: string
  descriptionId: string
  open: boolean
  setOpen: (open: boolean, reason: DialogOpenChangeReason) => void
  titleId: string
}

const DialogContext = createContext<DialogContextValue | null>(null)
const useBrowserLayoutEffect = typeof document === 'undefined' ? useEffect : useLayoutEffect

function useDialogContext(componentName: string) {
  const context = useContext(DialogContext)
  if (!context) throw new Error(`${componentName} must be rendered inside Dialog.Root`)
  return context
}

export function DialogRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open: controlledOpen,
}: DialogRootProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const open = controlledOpen ?? uncontrolledOpen
  const contentRef = useRef<HTMLDivElement | null>(null)
  const contentId = useId()
  const titleId = useId()
  const descriptionId = useId()

  const setOpen = useCallback(
    (nextOpen: boolean, reason: DialogOpenChangeReason) => {
      if (nextOpen === open) return
      if (controlledOpen === undefined) setUncontrolledOpen(nextOpen)
      onOpenChange?.(nextOpen, { reason })
    },
    [controlledOpen, onOpenChange, open],
  )

  const value = useMemo(
    () => ({ contentId, contentRef, descriptionId, open, setOpen, titleId }),
    [contentId, descriptionId, open, setOpen, titleId],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

export type DialogTriggerProps = React.ButtonHTMLAttributes<HTMLButtonElement>

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(function DialogTrigger(
  { onClick, type = 'button', ...props },
  forwardedRef,
) {
  const { contentId, open, setOpen } = useDialogContext('Dialog.Trigger')
  return (
    <button
      {...props}
      aria-controls={open ? contentId : undefined}
      aria-expanded={open}
      aria-haspopup="dialog"
      data-state={open ? 'open' : 'closed'}
      onClick={(event) => {
        onClick?.(event)
        if (!event.defaultPrevented) setOpen(true, 'trigger')
      }}
      ref={forwardedRef}
      type={type}
    />
  )
})

export type DialogPortalProps = {
  children: ReactNode
  container?: Element | DocumentFragment | null
}

export function DialogPortal({ children, container }: DialogPortalProps) {
  const { open } = useDialogContext('Dialog.Portal')
  const [portalNode, setPortalNode] = useState<HTMLDivElement | null>(null)

  useBrowserLayoutEffect(() => {
    if (!open) return

    const target = container ?? document.body
    const node = document.createElement('div')
    node.dataset.dialogPortal = ''
    target.appendChild(node)
    setPortalNode(node)

    return () => {
      node.remove()
      setPortalNode(null)
    }
  }, [container, open])

  if (!open || !portalNode) return null
  return createPortal(children, portalNode)
}

